import argparse
from datetime import date, datetime, timedelta
from pathlib import Path
import sqlite3

import categories
import config
import database


def _history_groups(connection):
    """Group exact sport/variant/weekday/time signatures, retaining distinct observation dates."""
    rows = connection.execute('''SELECT id,sport,variant,training_date,start_time
        FROM training_history ORDER BY id''').fetchall()
    if not rows:
        raise ValueError('Import training history before generating future ideas.')
    groups, dates = {}, []
    for row in rows:
        try:
            day = date.fromisoformat(row['training_date'])
        except (TypeError, ValueError):
            raise ValueError('The archive contains an invalid training date.') from None
        dates.append(day)
        if not row['sport'] or not row['sport'].strip():
            continue
        key = (row['sport'], row['variant'] or '', day.weekday(), row['start_time'])
        if key not in groups:
            groups[key] = {'history_id': row['id'], 'dates': set()}
        groups[key]['history_id'] = min(groups[key]['history_id'], row['id'])
        groups[key]['dates'].add(day)
    return max(dates), groups


def derive_weekly_patterns(connection):
    """Require three distinct weekly dates out of four, including the latest observed week.

    The anchor is the archive's latest date, not the computer's current date.
    Exact duplicate rows and repeated exports never count as extra weekly evidence.
    :return: anchor_date and a deterministically ordered list of eligible pattern dictionaries
    """
    anchor, groups = _history_groups(connection)
    first = anchor - timedelta(weeks=config.HISTORY_LOOKBACK_WEEKS) + timedelta(days=1)
    recent = anchor - timedelta(days=config.DAYS_PER_WEEK - 1)
    patterns = []
    # Course: L04 – sets count distinct training dates, rather than raw source-row multiplicity.
    for key in sorted(groups):
        observed = sorted(day for day in groups[key]['dates'] if first <= day <= anchor)
        if len(observed) < config.HISTORY_MIN_EVIDENCE_WEEKS or observed[-1] < recent:
            continue
        patterns.append({'history_id': groups[key]['history_id'], 'sport': key[0],
                         'variant': key[1], 'weekday': key[2], 'start_time': key[3],
                         'evidence_weeks': len(observed), 'first_seen': observed[0],
                         'last_seen': observed[-1]})
    return {'anchor_date': anchor, 'patterns': patterns}


def _forecast_window(start_date, now, anchor):
    """Select exactly four complete future weeks and reject past or non-Monday horizons."""
    if start_date is None:
        start_date = now.date() + timedelta(days=config.DAYS_PER_WEEK - now.weekday())
    if (type(start_date) is not date or start_date.weekday() != 0
            or start_date <= now.date() or start_date <= anchor):
        raise ValueError('Forecast start must be a future Monday after the observed history.')
    return start_date, start_date + timedelta(weeks=config.HISTORY_FORECAST_WEEKS)


def _series_for_pattern(connection, pattern, taxonomy):
    """Keep a stable local pattern ID without overwriting existing manually curated course data."""
    external_id = config.HISTORY_PATTERN_PREFIX + str(pattern['history_id'])
    existing = connection.execute('''SELECT id FROM series
        WHERE source=? AND external_id=?''', ('unisport', external_id)).fetchone()
    if existing is not None:
        return existing['id']
    title = pattern['sport']
    if pattern['variant'] and pattern['variant'] != title:
        title += ' · ' + pattern['variant']
    record = {'source': 'unisport', 'title': title}
    _, bundle_key = categories.assign_category(record, taxonomy)
    bundle = connection.execute('SELECT id FROM bundles WHERE key=?', (bundle_key,)).fetchone()
    if bundle is None:
        raise ValueError('Seed the project taxonomy before generating future ideas.')
    cursor = connection.execute('''INSERT INTO series
        (source,external_id,title,description,organizer,bundle_id,sport,location_type,is_recurring)
        VALUES (?,?,?,?,?,?,?,?,?)''',
        ('unisport', external_id, title,
         'Unverified projection from historical training dates. Duration is estimated.',
         'Unisport HSG', bundle['id'], pattern['sport'], 'tba', 1))
    return cursor.lastrowid


def _store_projected_event(connection, series_id, start, pattern, anchor, stamp):
    """Append a missing idea; existing or website-verified occurrences keep all their values."""
    existing = connection.execute('''SELECT e.id,p.kind FROM events e
        LEFT JOIN event_provenance p ON p.event_id=e.id
        WHERE e.series_id=? AND e.start_time=?''',
        (series_id, database.to_db_text(start))).fetchone()
    if existing is not None:
        return 'existing' if existing['kind'] == 'projected' else 'protected'
    # A missing end is an explicit app estimate, never evidence of the real course duration.
    end = start + timedelta(minutes=config.DEFAULT_DURATION_MINUTES)
    cursor = connection.execute('''INSERT INTO events
        (series_id,start_time,end_time,end_is_estimated,status) VALUES (?,?,?,?,?)''',
        (series_id, database.to_db_text(start), database.to_db_text(end), 1, 'unknown'))
    connection.execute('''INSERT INTO event_provenance
        (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
        VALUES (?,?,?,?,?)''',
        (cursor.lastrowid, 'projected', anchor.isoformat(), pattern['evidence_weeks'], stamp))
    return 'created'


def generate_training_forecast(connection, start_date=None, now=None):
    """Atomically append a four-week provisional plan; never reconcile or delete other events.

    :param connection: initialized, taxonomy-seeded SQLite connection without a pending transaction
    :param start_date: optional future Monday; default is the next complete week
    :param now: injected naive Zurich clock
    :return: aggregate counts and inclusive horizon dates; no private course text is printed
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before generating future ideas.')
    now = config.local_now(now)
    stamp = database.to_db_text(now)
    derived = derive_weekly_patterns(connection)
    anchor, patterns = derived['anchor_date'], derived['patterns']
    first, end = _forecast_window(start_date, now, anchor)
    if len(patterns) * config.HISTORY_FORECAST_WEEKS > config.MAX_RECORDS_PER_SOURCE:
        raise ValueError('The forecast exceeds the active-event source limit.')
    taxonomy = categories.load_taxonomy()
    counts = {'created': 0, 'existing': 0, 'protected': 0}
    # Course: A07 – course, dated occurrence and provenance form one complete transaction.
    with connection:
        for pattern in patterns:
            try:
                clock = datetime.strptime(pattern['start_time'], config.SOURCE_TIME_FORMAT).time()
            except (TypeError, ValueError):
                raise ValueError('The archive contains an invalid course start time.') from None
            series_id = _series_for_pattern(connection, pattern, taxonomy)
            for week in range(config.HISTORY_FORECAST_WEEKS):
                day = first + timedelta(weeks=week, days=pattern['weekday'])
                start = datetime.combine(day, clock)
                result = _store_projected_event(connection, series_id, start,
                                                pattern, anchor, stamp)
                counts[result] += 1
    return {'n_patterns': len(patterns), 'n_created': counts['created'],
            'n_existing': counts['existing'], 'n_protected': counts['protected'],
            'first_date': first.isoformat(), 'last_date': (end - timedelta(days=1)).isoformat(),
            'anchor_date': anchor.isoformat()}


def _start_date(text):
    """Parse an optional ISO date for the explicit command-line horizon."""
    try:
        return date.fromisoformat(text)
    except ValueError:
        raise argparse.ArgumentTypeError('Use YYYY-MM-DD for the start date.') from None


def main():
    """Create private historical projections only after an explicit Task 4 command."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--database', type=Path, default=config.TRAINING_HISTORY_DB)
    parser.add_argument('--start-date', type=_start_date)
    options = parser.parse_args()
    if not options.database.is_file():
        parser.exit(1, 'The private archive does not exist; run the Task 3 import first.\n')
    connection = None
    try:
        connection = database.get_connection(options.database)
        database.init_db(connection)
        categories.seed_categories(connection, categories.load_taxonomy())
        report = generate_training_forecast(connection, options.start_date)
    except (OSError, sqlite3.Error):
        parser.exit(1, 'Could not read or update the private training forecast.\n')
    except ValueError as error:
        parser.exit(1, str(error) + '\n')
    finally:
        if connection is not None:
            connection.close()
    print(f'{report["n_patterns"]} weekly patterns; {report["n_created"]} new provisional events; '
          f'{report["n_existing"]} existing projections; {report["n_protected"]} protected events.')
    print(f'Forecast: {report["first_date"]} to {report["last_date"]}; '
          f'historical observations through {report["anchor_date"]}.')
    print('All new events: projected, availability unknown, end estimated, location unknown.')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
